void handle_floorplan_request(WebEmSession *session, const request *req, reply *rep) {
    const char *idx = request_get_param(req, "idx");
    if (!idx || idx[0] == '\0') {
        return;
    }

    // Query the database for the image data
    unsigned char *image_data = NULL;
    size_t image_size = 0;
    int db_result = database_query_image_by_id(idx, &image_data, &image_size);
    if (db_result != 0 || !image_data || image_size == 0) {
        return;
    }

    // Set the reply content to the retrieved image
    reply_set_body(rep, image_data, image_size);

    // Determine the file extension based on the first byte
    const char *file_extension = NULL;
    if (image_data[0] == 0xFF) {
        // JPEG
        file_extension = ".jpg";
    } else if (image_data[0] == 0x89) {
        // PNG
        file_extension = ".png";
    } else if (image_data[0] == 0x47) {
        // GIF
        file_extension = ".gif";
    } else {
        // Default to unknown
        file_extension = ".bin";
    }

    // Set the attachment header with the determined file extension
    reply_set_header(rep, "Content-Disposition", "attachment", strlen("attachment") + strlen(file_extension) + 2, "filename=\"%s%s\"", "floorplan", file_extension);
}

void handle_floorplan_request(WebEmSession& session, const request& req, reply& rep) {
    const char* idx = webem_get_param(req, "idx");
    if (!idx || strlen(idx) == 0) {
        return;
    }

    unsigned char* image_data = NULL;
    size_t image_size = 0;
    int result = database_query_image(idx, &image_data, &image_size);
    if (result != 0 || image_data == NULL || image_size == 0) {
        return;
    }

    char* file_extension = NULL;

    // Determine file extension based on the first byte
    if (image_data[0] == 0x47) { // 'G' for GIF
        file_extension = "gif";
    } else if (image_data[0] == 0x89) { // For PNG
        file_extension = "png";
    } else if (image_data[0] == 0x46) { // 'F' for JPEG (could vary, but common)
        file_extension = "jpg";
    } else if (image_data[0] == 0x42) { // 'B' for BMP
        file_extension = "bmp";
    } else {
        free(image_data);
        return;
    }

    rep.content = (char*)image_data;
    rep.content_length = image_size;
    snprintf(rep.headers[rep.header_count].name, sizeof(rep.headers[rep.header_count].name), "Content-Disposition");
    snprintf(rep.headers[rep.header_count].value, sizeof(rep.headers[rep.header_count].value), "attachment; filename=floorplan.%s", file_extension);
    rep.header_count++;
}

void send_floorplan_image(WebEmSession& session, const request& req, reply& rep) {
    const char* idx = webem_request_get_param(req, "idx");
    if (!idx || strlen(idx) == 0) {
        return;
    }

    // Query the database for the image associated with the given ID.
    uint8_t* image_data = NULL;
    size_t image_size = 0;
    int success = database_get_image_by_id(idx, &image_data, &image_size);
    if (!success || image_data == NULL || image_size == 0) {
        return;
    }

    // Set the content of the reply with the image data.
    rep.body.assign((const char*)image_data, image_size);

    // Determine the file extension based on the first byte.
    const char* extension = "unknown";
    if (image_size > 0) {
        if (image_data[0] == 0x47) { // 'G' - GIF
            extension = "gif";
        } else if (image_data[0] == 0x89 && image_size > 1 && image_data[1] == 0x50) { // 'P' in PNG
            extension = "png";
        } else if (image_data[0] == 0x42 && image_size > 1 && image_data[1] == 0x4D) { // BM - BMP
            extension = "bmp";
        } else if (image_data[0] == 0xFF && image_size > 1 && image_data[1] == 0xD8) { // JPEG
            extension = "jpg";
        } else {
            extension = "bin";
        }
    }

    // Add attachment header with the determined file extension.
    webem_reply_set_header(rep, "Content-Disposition", "attachment; filename=floorplan.");
    webem_reply_set_header(rep, "Content-Type", "application/octet-stream");
}

void send_floorplan_image(WebEmSession& session, const request& req, reply& rep) {
    const std::string* idx = req.get_param("idx");
    if (!idx || idx->empty()) {
        return;
    }

    std::string image_data = query_database_for_image(*idx);
    if (image_data.empty()) {
        return;
    }

    rep.content = image_data;
    std::string extension = ".jpg";

    if (!image_data.empty()) {
        unsigned char first_byte = image_data[0];
        if (first_byte == 0x89) {
            extension = ".png";
        }
    }

    rep.headers["Content-Disposition"] = "attachment; filename=floorplan" + extension;
}

void send_floorplan_image(WebEmSession& session, const request& req, reply& rep) {
    const std::string idx = req.get("idx");
    if (idx.empty()) {
        return;
    }

    std::string image_data = query_database_for_image(idx);
    if (image_data.empty()) {
        return;
    }

    char first_byte = image_data[0];
    std::string file_extension;

    if (first_byte == '\xFF') {
        file_extension = ".jpg";
    } else if (first_byte == '\x89') {
        file_extension = ".png";
    } else {
        return;
    }

    rep.set_content(image_data);
    rep.add_header("Content-Disposition", "attachment; filename=floorplan" + file_extension);
}
